  "sources": {
   "startup.c": "/* Minimal Cortex-M startup: vector table, .data copy, .bss clear, call main. */\n#include <stdint.h>\n\nextern uint32_t _estack, _sidata, _sdata, _edata, _sbss, _ebss;\nint main(void);\n\nvoid Reset_Handler(void)\n{\n    uint32_t *src = &_sidata;\n    uint32_t *dst = &_sdata;\n    while (dst < &_edata) {\n        *dst++ = *src++;\n    }\n    for (dst = &_sbss; dst < &_ebss; dst++) {\n        *dst = 0;\n    }\n    main();\n    for (;;) {\n    }\n}\n\nvoid Default_Handler(void)\n{\n    for (;;) {\n    }\n}\n\nvoid HardFault_Handler(void)\n{\n    for (;;) {\n    }\n}\n\n__attribute__((section(\".vectors\"), used))\nstatic void *const vector_table[16] = {\n    &_estack,          /*  0: initial main stack pointer */\n    Reset_Handler,     /*  1: reset */\n    Default_Handler,   /*  2: NMI */\n    HardFault_Handler, /*  3: HardFault */\n    Default_Handler,   /*  4: MemManage */\n    Default_Handler,   /*  5: BusFault */\n    Default_Handler,   /*  6: UsageFault */\n    0, 0, 0, 0,        /*  7-10: reserved */\n    Default_Handler,   /* 11: SVCall */\n    Default_Handler,   /* 12: DebugMonitor */\n    0,                 /* 13: reserved */\n    Default_Handler,   /* 14: PendSV */\n    Default_Handler,   /* 15: SysTick */\n};\n",
   "dbg_tour.c": "/* tour: a first debug session. Sums a table, then blinks an LED forever. */\n#include \"bench.h\"\n\n#define LED_PIN 5u\n\nstatic const uint8_t samples[6] = {12, 7, 30, 5, 9, 21};\nuint32_t total;\n\nstatic uint32_t checksum(const uint8_t *data, uint32_t len)\n{\n    uint32_t sum = 0;\n    for (uint32_t i = 0; i < len; i++) {\n        sum += data[i];\n    }\n    return sum;\n}\n\nstatic void led_toggle(void)\n{\n    GPIO_OUT ^= 1u << LED_PIN;\n}\n\nint main(void)\n{\n    volatile uint32_t count = 0;\n    GPIO_DIR |= 1u << LED_PIN;\n    total = checksum(samples, 6);\n    for (;;) {\n        led_toggle();\n        count++;\n    }\n}\n"
  }
